require_once 'config.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $stmt=$pdo->prepare("SELECT j.*, u.name AS poster_name FROM jobs j JOIN users u ON u.id=j.posted_by WHERE j.id=? AND j.status='published'"); $stmt->execute([$id?:0]); $job=$stmt->fetch(); if(!$job){http_response_code(404);$pageTitle='Opportunity not found';require 'includes/header.php';echo '<section class="section"><div class="empty-state"><h2>We couldn’t find that opportunity.</h2><p>It may have been removed or is no longer available.</p><a class="button button-primary" href="jobs.php">Back to opportunities</a></div></section>';require 'includes/footer.php';exit;} $pageTitle=$job['title']; $user=current_user(); $applied=false; if($user){$s=$pdo->prepare('SELECT id FROM applications WHERE job_id=? AND user_id=?');$s->execute([$job['id'],$user['id']]);$applied=(bool)$s->fetchColumn();} require 'includes/header.php'; ?>
<section class="detail-wrap"><a class="back-link" href="jobs.php">← Back to opportunities</a><div class="detail-layout"><article class="detail-main"><div class="detail-company"><div class="company-logo logo-2"><?= e(initials($job['company_name'])) ?></div><div><strong><?= e($job['company_name']) ?></strong><span>Opportunity on Launchboard</span></div><span class="job-type"><?= e($job['category']) ?></span></div><h1><?= e($job['title']) ?></h1><div class="detail-meta"><span>⌖ <?= e($job['location']) ?></span><span>◷ Posted <?= date('M j, Y',strtotime($job['created_at'])) ?></span><span>▣ <?= $job['deadline']?'Apply by '.date('M j, Y',strtotime($job['deadline'])):'Open until filled' ?></span></div><div class="detail-divider"></div><h2>About this opportunity</h2><div class="job-description"><?= nl2br(e($job['description'])) ?></div><div class="detail-note"><span>✳</span><p><strong>A little encouragement</strong><br>You don't need to meet every requirement to take the first step. If this role excites you, consider applying.</p></div></article><aside class="apply-card"><div class="apply-card-top"><span class="eyebrow">MAKE YOUR MOVE</span><span class="apply-spark">✦</span></div><h2>Could this be your next step?</h2><p>Put yourself forward and let your potential speak.</p><div class="apply-facts"><div><span>Company</span><strong><?= e($job['company_name']) ?></strong></div><div><span>Location</span><strong><?= e($job['location']) ?></strong></div><div><span>Application deadline</span><strong><?= $job['deadline']?date('M j, Y',strtotime($job['deadline'])):'No fixed deadline' ?></strong></div></div><?php if(!job_is_open($job)): ?><button class="button button-disabled button-block" disabled>Applications closed</button><?php elseif($applied): ?><button class="button button-disabled button-block" disabled>✓ Application submitted</button><a class="text-link centered-link" href="my_applications.php">Track your application →</a><?php elseif($user && $user['role']==='student'): ?><a class="button button-primary button-block" href="apply.php?job_id=<?= (int)$job['id'] ?>">Apply for this role <span>↗</span></a><?php elseif(!$user): ?><a class="button button-primary button-block" href="login.php?next=<?= urlencode('job.php?id='.$job['id']) ?>">Sign in to apply <span>↗</span></a><p class="tiny-note">New here? <a href="register.php">Create a student account</a></p><?php else: ?><p class="tiny-note">Student accounts can apply for this opportunity.</p><?php endif; ?><div class="safe-note">♧ Your information stays connected to your application.</div></aside></div></section>
